/* Original learning activities adapted to the supplied writeshop sequence. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.REILearningPathCore=api})(typeof window!=='undefined'?window:this,()=>{
 const sources=[
  {id:'guidance',title:'Guidance during inquiry',citation:'Lazonder & Harmsen (2016)',url:'https://doi.org/10.3102/0034654315627366',finding:'A synthesis of 72 studies found benefits of guidance for inquiry activities, task performance and learning.',use:'Optional hints, examples and a manageable sequence.',limit:'The studies span different inquiry settings. They do not validate REI or guarantee independent research competence.'},
  {id:'retrieval',title:'Recall before rereading',citation:'Karpicke & Blunt (2011)',url:'https://pubmed.ncbi.nlm.nih.gov/21252317/',finding:'Experiments using science texts found benefits of retrieval practice on later comprehension and inference questions.',use:'Write an explanation from memory before opening the comparison answer.',limit:'Learning from science texts is narrower than conducting a research project. These adapted exercises have not been evaluated.'},
  {id:'sources',title:'Investigate the source',citation:'McGrew (2020)',url:'https://doi.org/10.1016/j.compedu.2019.103711',finding:'After eight lessons, 68 eleventh-grade students improved on three of four online-information evaluation tasks.',use:'Check who is behind a claim, inspect evidence and cross-check outside the original page.',limit:'This pre/post study concerns civic online information. It does not establish scholarly article quality or a causal effect of REI.'},
  {id:'comparison',title:'Explain meaningful differences',citation:'Rittle-Johnson & Star (2009)',url:'https://doi.org/10.1037/a0014224',finding:'An experiment with 162 school students found that the type of comparison mattered for learning equation-solving methods.',use:'Compare alternatives and explain which differences matter, rather than copying an answer.',limit:'The original task was mathematics. Using comparison in research-design exercises is an instructional adaptation, not direct proof of transfer.'},
  {id:'revision',title:'Use feedback to revise',citation:'Cho & MacArthur (2010)',url:'https://doi.org/10.1016/j.learninstruc.2009.08.006',finding:'A study of 28 undergraduates examined how peer/expert feedback related to revisions and writing quality.',use:'Request specific comments, decide what to change and record a revision rationale.',limit:'The small writing study does not validate automated feedback or guarantee better research. Peer review here happens outside REI.'},
  {id:'spacing',title:'Return on another day',citation:'Dunlosky et al. (2013)',url:'https://doi.org/10.1177/1529100612453266',finding:'A review rated practice testing and distributed practice highly across the learning conditions it examined.',use:'Keep a revisit list and repeat a short explanation later.',limit:'REI does not prescribe a scientifically optimal interval or infer mastery from a visit.'}
 ];
 const steps=[
  {id:'mindset',short:'Begin with a purpose',seminar:'Opening · The Research Mindset',title:'Notice a problem. Question your first explanation.',intro:'Research starts with curiosity, but a convincing answer needs evidence. You can follow this path after the writeshop or use it independently.',remember:'An observation is a starting point, not an explanation.',concepts:['Separate what you observed from why you think it happened.','Name what you need to find out and who could benefit.','Keep a question open to evidence that might change your mind.'],fields:[['interest','What have you noticed?','Describe an issue in your field without assuming its cause.'],['purpose','Why is it worth investigating?','Who is affected, and what could a better understanding change?'],['assumption','What might you be assuming?','Write one assumption and an observation that could challenge it.']],example:'Fictional example: a campus help desk has long queues. “Students arrive late” is one possible explanation; service times, staffing and arrival patterns are alternatives.',links:[[0,'Learn how to choose a topic']],tool:['#notebook','Keep other ideas in your notebook'],practice:'recall'},
  {id:'question',short:'Shape your question',seminar:'Phase 1 · Developing Meaningful Research Ideas',title:'Turn an interest into a question you can investigate.',intro:'Keep topic, problem and question distinct. Narrow the setting and aim to something you can realistically access.',remember:'Topic → evidence of a problem → focused question.',concepts:['A topic names an area; a problem explains an evidenced uncertainty or difficulty.','A research question states what you want to find out.','Access, time, ethics and available evidence constrain a feasible question.'],fields:[['topic','Your topic','Name the area you want to study.'],['problem','The problem and its evidence','What is known? Name a source or record that needs checking.'],['question','Your working research question','Specify the people/materials, setting and aim.'],['scope','Your boundary','What can you access, and what will you leave outside this study?']],example:'Fictional example: “Campus transport” is a topic. “How do first-year commuters at one campus describe disruptions to their study plans?” is a bounded qualitative question; evidence of the problem still needs checking.',links:[[1,'Separate the topic from the problem'],[5,'Develop a research question']],tool:['#resource/framework','Use the framework guide'],practice:'question'},
  {id:'search',short:'Find credible sources',seminar:'Phase 2 · Mastering the Search and Evaluation of Information',title:'Make your search traceable, not just longer.',intro:'Try a query, inspect the results and record why a source belongs in your study. Use library access or sources you can legally open.',remember:'Search → investigate → keep a reason.',concepts:['Group synonyms for each main concept; adapt operators to your database.','Check authorship, venue, evidence, publication context and external corroboration.','A polished website, DOI or high citation count does not alone establish quality. Keep source details and distinguish quotations from your own wording.'],fields:[['query','Your first search query','Record concept groups and the database you intend to use.'],['source','A source worth checking','Record its title, author/year and DOI or URL if available.'],['evaluation','Why keep it, and what needs checking?','Consider relevance, methods, limitations and independent checks.'],['searchchange','How will you improve the next search?','What terms, fields, filters or missing perspectives will you change?']],example:'Fictional search: (commuter OR commuting) AND (student OR undergraduate) AND (study OR learning). Check the database syntax, inspect relevance and record the actual search date in your research log.',links:[[2,'Practice scholarly searching']],tool:['#research','Open a project library when you need one'],practice:'verify'},
  {id:'synthesis',short:'Connect what studies show',seminar:'Phase 3 · The Art of Literature Review and Synthesis',title:'Explain the pattern without losing the differences.',intro:'Compare findings alongside methods, populations and limitations. A literature map records relationships you can justify.',remember:'Compare studies. Explain differences. Bound the gap.',concepts:['A synthesis connects sources around an idea rather than listing one summary after another.','Disagreement may reflect measurement, setting, sampling or uncertainty.','A gap in the sources you reviewed is provisional; an incomplete search cannot prove novelty.'],fields:[['comparison','Two sources and a meaningful difference','Name each source and compare its method, setting and finding.'],['pattern','Your provisional synthesis','What seems to agree or differ, and what might explain it?'],['gap','An uncertainty worth examining','Bound your statement to the sources reviewed; explain why it matters.']],example:'Fictional studies: a survey finds an association between commute length and study hours; interviews describe planning challenges. They address related issues but use different evidence and do not establish that commuting causes lower achievement.',links:[[3,'Compare literature'],[4,'Make a defensible gap claim']],tool:['#research','Use Evidence and Synthesis in a project'],practice:'gap'},
  {id:'blueprint',short:'Build a research blueprint',seminar:'Phase 4 · Connecting Problems Evidence and Solutions',title:'Make each method answer a real question.',intro:'Bring your question, evidence, objective and method into one chain. This is a preliminary direction to discuss with a supervisor, not a finished or approved proposal.',remember:'Question → evidence needed → method → permitted claim.',concepts:['An objective states an achievable contribution; your framework explains the proposed relationships or ideas.','Choose collection and analysis together, with a sampling/access rationale.','Address consent, privacy, feasibility and the limits of the claims your design can support.'],fields:[['objective','One achievable objective','What will your study describe, estimate, interpret, compare or evaluate?'],['framework','Your preliminary framework','Describe concepts and proposed relationships; include a hypothesis only if your design calls for one. Separate assumptions from established findings.'],['method','Evidence collection and analysis','Who/what, how selected, what collected, how analyzed, and why that fits.'],['ethics','Ethics feasibility and claim limits','Name access/consent/privacy needs, practical constraints and what your design cannot establish.']],example:'Fictional alignment: to understand commuter students’ experiences, use justified participant selection, consent-based interviews and an explained qualitative analysis. A one-time interview study cannot estimate prevalence for all students.',links:[[6,'Make objectives useful'],[7,'Justify methods and analysis']],tool:['#research','Use the project Design room for a fuller plan'],practice:'alignment'},
  {id:'reflection',short:'Review and keep improving',seminar:'Phase 5 · Integrating the Research Foundation',title:'Use another perspective to strengthen your next draft.',intro:'If you attended the seminar, revisit an insight from the speaker’s research experience. If not, use a worked example in the lessons. Ask what you can transfer to your own field.',remember:'Explain your choices. Seek feedback. Revise deliberately.',concepts:['Trace the argument from problem to evidence and method.','Ask a peer or supervisor for comments on a specific uncertainty.','Revisit a short explanation on another day, then compare and improve it.'],fields:[['lesson','A decision or lesson you can transfer','Name its source: seminar discussion, worked example or real research experience.'],['feedback','A question for a peer or supervisor','What specific reasoning needs review? No message is sent from REI.'],['next','Your next research action','Name a concrete action and the evidence or decision it should produce.']],example:'Fictional reflection: “The example made recruitment access visible. Before promising a sample, I will check permission and explain how restricted access limits my claims.”',links:[[8,'Audit and develop the proposal']],tool:['#workbook','Review your assembled blueprint'],practice:'review'}
 ];
 const activities=[
  {id:'recall',title:'Explain it from memory',kind:'Recall and compare',evidence:['retrieval','spacing'],prompt:'Without opening the lessons, explain the difference between a research topic, a problem and a question. Use an example from your own field.',model:'A topic names an area; a problem describes an evidenced difficulty or uncertainty; a question specifies what the study seeks to find out. A useful explanation keeps them connected and names what still needs evidence.',transfer:'Rewrite your example so the problem is not an unsupported assumption. Return on another day and explain the distinction again without looking.'},
  {id:'question',title:'Repair an overbroad question',kind:'Compare and explain',evidence:['comparison','guidance'],prompt:'Fictional starting point: “Does technology improve everyone’s lives?” Write a feasible research question and explain what you deliberately excluded.',model:'A bounded revision could ask how a defined group describes using one technology for a specific task in one setting. Feasibility also requires a recruitment/access plan. A narrower question is not automatically important or ethically acceptable.',transfer:'Apply the same decisions to your own topic. Explain how your design would limit the answer.'},
  {id:'verify',title:'Investigate a source claim',kind:'Source evaluation',evidence:['sources'],prompt:'A fictional article claims a learning app doubles research skill. It has a polished design, no methods, and links only to the developer. What would you check before citing the claim?',options:['Trust the professional design','Investigate the author, original evidence and independent coverage','Treat a popularity count as proof'],best:1,feedback:['Appearance does not establish the quality of the evidence.','This addresses provenance and corroboration; you must still inspect the underlying study and its fit.','Popularity is not a substitute for methods, transparent results or independent checks.'],model:'Leave the page to investigate who is responsible, locate the original study, inspect its comparison group and skill measure, and seek independent coverage. Record what you could verify and what remains unsupported.',transfer:'Use the same checks on one real source. Record its DOI/URL, a reason to use it and a limitation. Do not enter private participant information.'},
  {id:'gap',title:'Explain a disagreement',kind:'Synthesis practice',evidence:['comparison','guidance'],prompt:'Fictional Study A surveys 200 volunteers and finds an association between commute length and self-reported study time. Study B interviews 12 commuters about planning challenges. Write a synthesis and one bounded unanswered question.',model:'The studies illuminate different aspects of commuting and study: an association in one volunteer sample and accounts of planning in another. Neither establishes a causal effect or a universal gap. Compare context, selection and measures before proposing an explanation.',transfer:'Write the next search you would run before claiming novelty. Explain why the uncertainty matters rather than saying “no one has studied it.”'},
  {id:'claim',title:'Keep a claim inside its evidence',kind:'Claim boundary check',evidence:['guidance','comparison'],prompt:'A fictional one-time survey finds that students reporting more sleep also report higher grades. Choose the most defensible starting interpretation, then explain a limitation.',options:['More sleep caused the higher grades','The two self-reported measures are associated in this sample','The result applies to every university'],best:1,feedback:['The survey alone does not rule out confounding, reverse direction or reporting error.','This keeps the claim within the study; uncertainty, selection and measurement still need attention.','The sampling and setting do not justify universal generalization.'],model:'Describe an association in the sampled responses. Consider workload, health, prior performance and reporting error. A larger sample alone would not establish causation.',transfer:'Rewrite one claim from your own reading so it names its population, evidence type and boundary.'},
  {id:'alignment',title:'Repair a method mismatch',kind:'Design reasoning',evidence:['comparison','guidance'],prompt:'A fictional project asks how students experience feedback, but proposes only a count of submitted assignments. Explain the mismatch and propose collection and analysis that could address the question.',model:'Submission counts describe behavior but do not directly show how feedback is experienced. Consent-based accounts could address experience if sampling and analysis are justified. Another valid revision is to change the question to match the available records.',transfer:'For your own objective, name evidence needed, selection, collection, analysis and the claim each can support. Explain one alternative you rejected.'},
  {id:'review',title:'Give feedback that leads to a revision',kind:'Review and revision',evidence:['revision'],prompt:'Fictional draft: “We will interview some students and prove our system works.” Write feedback that asks for a clearer objective, justified evidence and a claim the method could support.',model:'Ask what “works” means, whose experience or outcome matters, how participants will be selected, and how the data will be analyzed. Suggest a specific revision while leaving the author responsible for the decision. Feedback is not institutional approval.',transfer:'Export your blueprint and ask a peer or supervisor one focused question outside REI. Record a comment, what you changed and why; leave names/private feedback out if unnecessary.'},
  {id:'revisit',title:'Return to a fresh explanation',kind:'Spaced practice',evidence:['spacing','retrieval'],prompt:'Choose a concept you studied earlier. Before opening your notes, explain it and apply it to a new situation. If this is your first visit, do the recall activity now and return on another day.',model:'Compare your explanation against the relevant lesson, identify a missing distinction and correct it. Revisit timing should suit your learning context; REI does not calculate an optimal interval or certify retention.',transfer:'Write the correction and a different example. Your revisit list is a personal learning aid, not an attendance record or mastery score.'}
 ];
 const allFields=steps.flatMap(s=>s.fields.map(f=>f[0]));
 function normalize(raw){const out={version:1,last:0,fields:{},practice:{}};if(!raw||typeof raw!=='object')return out;if(Number.isInteger(raw.last)&&raw.last>=0&&raw.last<steps.length)out.last=raw.last;for(const k of allFields)if(typeof raw.fields?.[k]==='string')out.fields[k]=raw.fields[k].slice(0,3000);for(const a of activities){const r=raw.practice?.[a.id];if(!r||typeof r!=='object')continue;out.practice[a.id]={attempt:typeof r.attempt==='string'?r.attempt.slice(0,3000):'',revision:typeof r.revision==='string'?r.revision.slice(0,3000):'',revealed:r.revealed===true,choice:Number.isInteger(r.choice)&&r.choice>=0&&r.choice<(a.options?.length||0)?r.choice:null,reviewed:typeof r.reviewed==='string'&&Number.isFinite(Date.parse(r.reviewed))?r.reviewed:null}}return out}
 function next(raw){const s=normalize(raw);return steps.findIndex(step=>step.fields.some(([k])=>!s.fields[k]?.trim()))}
 function markdown(raw){const s=normalize(raw);return '# My research learning workbook\n\nA preliminary blueprint and practice record. Review sources, methods and ethics with a supervisor.\n\n'+steps.map(step=>'## '+step.short+'\n\n'+step.fields.map(([k,label])=>'### '+label+'\n\n'+(s.fields[k]?.trim()||'[Not recorded]')).join('\n\n')).join('\n\n')+'\n\n## Practice and revisions\n\n'+activities.filter(a=>s.practice[a.id]).map(a=>{const r=s.practice[a.id];return '### '+a.title+(a.options&&Number.isInteger(r.choice)?'\n\nChosen interpretation: '+a.options[r.choice]:'')+'\n\nInitial attempt: '+r.attempt+'\n\nRevision: '+(r.revision||'[Not recorded]')}).join('\n\n')}
 function searchEntries(raw){const s=normalize(raw),out=[];steps.forEach((step,i)=>step.fields.forEach(([key,title])=>{if(s.fields[key]?.trim())out.push({href:'#learn/'+i,kind:'Learning workbook',title,description:s.fields[key]})}));activities.forEach(a=>{const r=s.practice[a.id];if(r?.attempt?.trim()||r?.revision?.trim())out.push({href:'#practice/'+a.id,kind:'Practice response',title:a.title,description:[r.attempt,r.revision].filter(Boolean).join(' ')})});return out}
 return {sources,steps,activities,normalize,next,markdown,searchEntries};
});
